use crate::aap::caps::state_read;

struct Node;

// NOTE: This node's entire authority is `aap:caps/state-read@0.1.0`.
// It deliberately does NOT write to a log file or call any HTTP endpoint:
// neither a filesystem nor an http-client capability is granted by the
// node's `with` clause, so those requests are out of scope for this body.

/// Keys under which the subscription list may be stored. The store cannot be
/// enumerated, so we ask only for keys we already know.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds", "list", "all"];

fn push_unique(out: &mut Vec<String>, s: &str) {
    let s = s.trim();
    if s.is_empty() {
        return;
    }
    if !out.iter().any(|u| u == s) {
        out.push(s.to_string());
    }
}

/// Extract every JSON string literal from `text`, unescaped.
fn json_strings(text: &str) -> Vec<String> {
    let mut found = Vec::new();
    let mut chars = text.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut s = String::new();
        let mut closed = false;
        while let Some(c) = chars.next() {
            match c {
                '"' => {
                    closed = true;
                    break;
                }
                '\\' => match chars.next() {
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\u{8}'),
                    Some('f') => s.push('\u{c}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            match chars.next().and_then(|h| h.to_digit(16)) {
                                Some(d) => code = code * 16 + d,
                                None => break,
                            }
                        }
                        if let Some(ch) = char::from_u32(code) {
                            s.push(ch);
                        }
                    }
                    Some(other) => s.push(other),
                    None => break,
                },
                other => s.push(other),
            }
        }
        if closed {
            found.push(s);
        }
    }
    found
}

fn parse_into(out: &mut Vec<String>, value: &str) {
    let trimmed = value.trim();
    if trimmed.starts_with('[') {
        for s in json_strings(trimmed) {
            push_unique(out, &s);
        }
    } else if trimmed.starts_with('{') {
        // An object: keep only the strings that look like URLs, so that
        // field names are not mistaken for subscriptions.
        for s in json_strings(trimmed) {
            if s.contains("://") {
                push_unique(out, &s);
            }
        }
    } else {
        for line in trimmed.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            for part in line.split(|c: char| c == ',' || c.is_whitespace()) {
                let part = part.trim_matches(|c: char| c == '"' || c == '\'');
                push_unique(out, part);
            }
        }
    }
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();

        for key in KEYS {
            if let Some(value) = state_read::get(key) {
                parse_into(&mut urls, &value);
                if !urls.is_empty() {
                    break;
                }
            }
        }

        if urls.is_empty() {
            // The contract requires `present(urls)`. With no subscriptions in
            // the store there is no honest output to produce, and fabricating
            // one is not an option: fail the node rather than violate `ensures`.
            panic!("no subscriptions found in state store");
        }

        SubscriptionList { urls }
    }
}

export!(Node);
